const lead      = $('Avaliar Duplicado').first().json;
const aiOutput  = $input.first().json;

// Extrai o texto gerado — compatível com resposta direta do LLM node
let briefing = '';
try {
  briefing = aiOutput?.text
          ?? aiOutput?.choices?.[0]?.message?.content
          ?? aiOutput?.message?.content
          ?? String(aiOutput ?? '');
} catch (e) {
  briefing = '';
}

return [{ json: { ...lead, briefing_ia: briefing.trim() } }];

const result = $input.first().json;
const lead   = $('Extrair Briefing').first().json;

const inserted = Array.isArray(result) ? result[0] : result;
const leadId   = inserted?.id ?? lead.lead_id_existente ?? null;

if (!leadId) {
  console.error('Nenhum lead_id disponível:', JSON.stringify(result));
  return [];
}

const acao = lead.lead_existente ? 'atualizado' : 'inserido';
console.log(`Lead ${acao}: ${leadId} — ${lead.nome} (${lead.classificacao}, score ${lead.score}, temperature ${lead.temperature})`);
return [{ json: { lead_id: leadId, lead } }];
